package org.basaltmc.auth

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.uuid.ExperimentalUuidApi
import kotlin.uuid.Uuid

/**
 * Golden vectors generated by running the real `UUID.nameUUIDFromBytes` on a JDK, matching what
 * vanilla's `UUIDUtil.createOfflinePlayerUUID` produces.
 */
@OptIn(ExperimentalUuidApi::class)
class OfflineUuidTest {
    @Test
    fun matchesJdkNameUUIDFromBytes() {
        assertEquals(Uuid.parse("5627dd98-e6be-3c21-b8a8-e92344183641"), OfflineUuid.forUsername("Steve"))
        assertEquals(Uuid.parse("b50ad385-829d-3141-a216-7e7d7539ba7f"), OfflineUuid.forUsername("Notch"))
        assertEquals(Uuid.parse("fc5bc365-aedf-30a8-8b89-04e462e29bde"), OfflineUuid.forUsername(""))
        assertEquals(Uuid.parse("52428a0e-1e30-3cb1-976c-e728b2614047"), OfflineUuid.forUsername("a"))
    }

    @Test
    fun isDeterministic() {
        assertEquals(OfflineUuid.forUsername("Alex"), OfflineUuid.forUsername("Alex"))
    }
}
